{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SQCOM_REPLEN_DEC_2025 AS WITH SALES AS ( SELECT CREATED_AT, branch_code, store_name, sku, CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT(SKU, LENGTH(SKU) - LENGTH(REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1))) - 1) ELSE SKU END AS sku_group, category, REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1)) AS size, SUM(QUANTITY) AS SOLD_QTY, SUM(SUM(QUANTITY)) OVER (PARTITION BY branch_code, CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT( SKU, LENGTH(SKU) - LENGTH( REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1))) - 1) ELSE SKU END) / 7 AS ROS FROM SNITCH_DB.MAPLEMONK.OMNI_ORDER_PROCESSING_META WHERE (LOCATION LIKE \'%BOHQ%\' OR LOCATION LIKE \'%BOH1Q%\') AND status NOT LIKE \'%CANCELLED%\' AND CAST(CREATED_AT AS DATE) = CURRENT_DATE - 1 GROUP BY 1,2,3,4,5,6,7 ), Inventory AS ( SELECT branch_code, STORE_NAME, sku, CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT(SKU, LENGTH(SKU) - LENGTH(REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1))) - 1) ELSE SKU END AS sku_group, REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1)) AS size, category_code, SUM(inventory_total) AS inventory FROM snitch_db.maplemonk.omni_inventory_meta WHERE location LIKE \'%BOH1Q%\' OR location like \'%BOHQ%\' GROUP BY 1,2,3,4,5,6 ), priority_defined as ( SELECT CAST(v.store_code AS INT) AS BRANCH_CODE, CAST(v.priority AS INT) AS PRIORITY, ROW_NUMBER() OVER ( ORDER BY CAST(v.priority AS INT) ) AS priority_order FROM ( SELECT 13 AS store_code, 1 AS priority union all SELECT 52 AS store_code, 2 AS priority union all SELECT 73 AS store_code, 3 AS priority ) v ), replen_size_thresholds AS ( SELECT s.branch_code, pd.priority, s.sku, s.sku_group, s.category, s.size, COALESCE(s.sold_qty,0) AS sold_qty, COALESCE(i.inventory, 0) AS inventory, CASE WHEN UPPER(TRIM(s.category)) IN ( \'HOODIES\',\'JACKETS\',\'OVERSHIRT\',\'SHIRTS\',\'SWEATERS\',\'SWEATSHIRTS\',\'T-SHIRTS\') THEN CASE UPPER(TRIM(s.size)) WHEN \'S\' THEN GREATEST(2 - COALESCE(i.inventory,0), 0) WHEN \'M\' THEN GREATEST(4 - COALESCE(i.inventory,0), 0) WHEN \'L\' THEN GREATEST(3 - COALESCE(i.inventory,0), 0) WHEN \'XL\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'XS\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'XXL\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) ELSE 0 END WHEN UPPER(TRIM(s.category)) IN ( \'CARGO PANTS\',\'JEANS\',\'JOGGERS\',\'TRACKPANTS\',\'SHORTS\',\'TROUSERS\') THEN CASE TRIM(s.size) WHEN \'30\' THEN GREATEST(3 - COALESCE(i.inventory,0), 0) WHEN \'32\' THEN GREATEST(4 - COALESCE(i.inventory,0), 0) WHEN \'34\' THEN GREATEST(3 - COALESCE(i.inventory,0), 0) WHEN \'36\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'28\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'38\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) ELSE 0 END ELSE 0 END AS REPLEN_UNITS FROM SALES s LEFT JOIN Inventory i ON s.branch_code=i.branch_code and s.sku_group = i.sku_group AND UPPER(TRIM(s.size)) = UPPER(TRIM(i.size)) left join priority_defined pd on s.branch_code = pd.branch_code ), ranked_stores AS ( SELECT BRANCH_CODE_PRIORITY, short_name AS region FROM SNITCH_DB.MAPLEMONK.GOOGLE_SHEET_FRESH_PRIORITY ), warehouse_stock AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.LIVE_INV_WAREHOUSE_offline_replen WHERE units_on_hand > 1 ), warehouse_preference AS ( SELECT r.SKU, r.branch_code, r.REPLEN_UNITS, rs.region, r.PRIORITY, w.facility, w.units_on_hand, CASE WHEN rs.region = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN rs.region = \'North\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 2 WHEN rs.region = \'South\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 1 WHEN rs.region = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM replen_size_thresholds r JOIN warehouse_stock w ON r.SKU = w.SKU LEFT JOIN ranked_stores rs ON r.branch_code = rs.BRANCH_CODE_PRIORITY WHERE NOT (rs.region = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\') ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU, branch_code ORDER BY base_priority ASC, units_on_hand DESC, facility ) AS warehouse_order FROM warehouse_preference ), allocation_base AS ( SELECT o.SKU, o.branch_code, o.PRIORITY, o.region, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, o.base_priority, COALESCE( SUM(o.REPLEN_UNITS) OVER( PARTITION BY o.SKU, o.facility ORDER BY o.base_priority ASC, o.PRIORITY ASC, o.branch_code ASC, o.warehouse_order ASC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) AS cum_req_before_fac, (o.units_on_hand - COALESCE( SUM(o.REPLEN_UNITS) OVER( PARTITION BY o.SKU, o.facility ORDER BY o.base_priority ASC, o.PRIORITY ASC, o.branch_code ASC, o.warehouse_order ASC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) ) AS remaining_facility_before FROM ordered_warehouses o ), allocation_with_stop AS ( SELECT a.*, GREATEST(LEAST(a.remaining_facility_before, a.REPLEN_UNITS), 0) AS allocatable_here, COALESCE( SUM(GREATEST(LEAST(remaining_facility_before, REPLEN_UNITS), 0)) OVER ( PARTITION BY SKU, branch_code ORDER BY base_priority ASC, units_on_hand DESC, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) AS cum_allocatable_before_store FROM allocation_base a ), final_rpL as ( SELECT SKU, branch_code, region, PRIORITY, facility, warehouse_order, REPLEN_UNITS, units_on_hand, base_priority, LEAST( GREATEST(REPLEN_UNITS - cum_allocatable_before_store, 0), GREATEST(allocatable_here, 0) ) AS allocated_units FROM allocation_with_stop WHERE LEAST( GREATEST(REPLEN_UNITS - cum_allocatable_before_store, 0), GREATEST(allocatable_here, 0) ) > 0 ORDER BY SKU, base_priority, PRIORITY, branch_code, warehouse_order) select * from final_rpl;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            